import { NgComponentOutlet } from '@angular/common';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import {
  Default as DefaultExample,
  LeftSide as LeftSideExample,
  BottomSheet as BottomSheetExample,
} from '../../examples/overlays/pixel-drawer.examples';

const meta: Meta = {
  title: 'UI Kit / Overlays / PixelDrawer',
  tags: ['autodocs', 'status-stable', 'cat-overlays'],
  decorators: [moduleMetadata({ imports: [NgComponentOutlet] })],
  parameters: {
    controls: { disable: true },
    docs: {
      description: { component: 'Side-anchored modal panel (right/left/top/bottom) with focus trap, scroll lock and Escape-to-close.' },
    },
  },
};

export default meta;
type Story = StoryObj;

/** Default */
export const Default: Story = {
  name: 'Default',
  tags: ['example-default'],
  render: () => ({ props: { example: DefaultExample }, template: '<ng-container *ngComponentOutlet="example" />' }),
  parameters: {
    docs: {
      source: { language: 'typescript', code: 'import { Component, signal } from \'@angular/core\';\nimport { PixelDrawer, PixelDrawerBody, PixelDrawerFooter, PixelDrawerHeader } from \'@pxlkit/ui-kit-angular\';\n\n@Component({\n  imports: [PixelDrawer, PixelDrawerHeader, PixelDrawerBody, PixelDrawerFooter],\n  template: `\n    <button type="button" (click)="open.set(true)">Open drawer</button>\n    <pxl-drawer [(open)]="open" title="Settings">\n      <pxl-drawer-header>\n        <span>Settings</span>\n        <button type="button" (click)="open.set(false)">Close</button>\n      </pxl-drawer-header>\n      <pxl-drawer-body>\n        <p>Drawer content goes here.</p>\n      </pxl-drawer-body>\n      <pxl-drawer-footer>\n        <button type="button" (click)="open.set(false)">Done</button>\n      </pxl-drawer-footer>\n    </pxl-drawer>\n  `,\n})\nexport class Default {\n  readonly open = signal(false);\n}' },
    },
  },
};

